-- ============================================================
-- EngLear — grammar topics A1–C2 (titles in the 11 interface languages).
-- Idempotent; run after 0018. Adds rows only: an existing code is left as it is.
-- ============================================================

on conflict (code) do nothing;

-- the starter library lesson on this topic
update public.lessons set grammar_topic_id = (select id from public.grammar_topics where code = 'present-simple')
 where scope = 'library' and source = 'import' and title = 'Present Simple: he, she, it' and grammar_topic_id is null;
